// The barrel (src/index.ts, generated by scripts/gen-index.mjs) re-exports every item module. `export *` silently
// drops a name that two modules export, so this test fails on any duplicate instead.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import * as barrel from '../src/index';

const modules = [...readFileSync(join(__dirname, '..', 'src', 'index.ts'), 'utf8').matchAll(/export \* from '\.\/([^']+)';/g)].map((m) => m[1]!);

describe('package barrel', () => {
  it('re-exports every name of every module, with no duplicate and no default export', async () => {
    // A module may re-export a sibling's binding (theme-toggle re-exports theme-toggle.theme): same value, no clash.
    const owners = new Map<string, string[]>();
    const values = new Map<string, Set<unknown>>();
    for (const m of modules) {
      const mod = (await import(`../src/${m}.tsx`).catch(() => import(`../src/${m}.ts`))) as Record<string, unknown>;
      expect(Object.keys(mod), m).not.toContain('default');
      for (const [name, value] of Object.entries(mod)) {
        owners.set(name, [...(owners.get(name) ?? []), m]);
        values.set(name, (values.get(name) ?? new Set()).add(value));
      }
    }
    const duplicates = [...owners].filter(([n]) => values.get(n)!.size > 1).map(([n, by]) => `${n}: ${by.join(', ')}`);
    expect(duplicates).toEqual([]);
    expect(Object.keys(barrel).sort()).toEqual([...owners.keys()].sort());
  });

  it('exports restoreTheme and the components', () => {
    expect(typeof barrel.restoreTheme).toBe('function');
    expect(typeof barrel.Button).toBe('function');
  });
});
